\begin{verbatim}
free_response_1dof(m = 1., t = 0.:1e-3:2.)
\end{verbatim}
Launch an interactive application to visualize the free response of a single-degree-of-freedom (SDOF) system

\textbf{Inputs}

\begin{itemize}
\item \texttt{m}: Mass of the SDOF system (default: 1.0)


\item \texttt{t}: Time vector over which the response is computed (default: 0.0   to 2.0 seconds with a step of 1e-3)

\end{itemize}
\textbf{Output}

\begin{itemize}
\item App

\end{itemize}

\begin{verbatim}
forced_response_1dof(m, t, r, Fmax, xbmax)
\end{verbatim}
Launch an interactive application to visualize the forced response of a single-degree-of-freedom (SDOF) system

\textbf{Inputs}

\begin{itemize}
\item \texttt{m}: Mass of the system (default: 1.0)


\item \texttt{t}: Time vector (default: 0.:1e-3:2.)


\item \texttt{r}: Reduced frequency vector (default: 0.:0.005:5.)


\item \texttt{Fmax}: Maximum excitation force (default: 20.0)


\item \texttt{xbmax}: Maximum base displacement (default: 2.0)

\end{itemize}
\textbf{Output}

\begin{itemize}
\item App

\end{itemize}

\begin{verbatim}
free_response_2dof(m1, m2, t)
\end{verbatim}
Launch an interactive application to visualize the free response of a two-degree-of-freedom (2DOF) system

\textbf{Inputs}

\begin{itemize}
\item \texttt{m1}: Mass of the first degree of freedom (default: 1.0)


\item \texttt{m2}: Mass of the second degree of freedom (default: 1.0)


\item \texttt{t}: Time vector over which the response is computed (default: 0.0 to 2.0 seconds with a step of 1e-3)

\end{itemize}
\textbf{Output}

\begin{itemize}
\item App

\end{itemize}

\begin{verbatim}
forced_response_2dof(m1, m2, t, freq)
\end{verbatim}
Launch an interactive application to visualize the forced response of a two-degree-of-freedom (2DOF) system

\textbf{Inputs}

\begin{itemize}
\item \texttt{m1}: Mass of the first degree of freedom (default: 1.0)


\item \texttt{m2}: Mass of the second degree of freedom (default: 1.0)


\item \texttt{t}: Time vector over which the response is computed (default: 0.0 to 5.0 seconds with a step of 1e-3)


\item \texttt{freq}: Frequency vector over which the transfer function is computed (default: 0.0 to 30.0 Hz with a step of 0.01)

\end{itemize}
\textbf{Output}

\begin{itemize}
\item App

\end{itemize}
